select 'transactions' as src, count(*) as n_rows from read_parquet('s3://bronze/topics/transactions.public.transactions/event_date=*/*.parquet', hive_partitioning=true, union_by_name=true) union all select 'accounts' as src, count(*) as n_rows from read_parquet('s3://bronze/topics/transactions.public.accounts/event_date=*/*.parquet', hive_partitioning=true, union_by_name=true) union all select 'users' as src, count(*) as n_rows from read_parquet('s3://bronze/topics/transactions.public.users/event_date=*/*.parquet', hive_partitioning=true, union_by_name=true) union all select 'account_holders' as src, count(*) as n_rows from read_parquet('s3://bronze/topics/transactions.public.account_holders/event_date=*/*.parquet', hive_partitioning=true, union_by_name=true) union all select 'ledger_entries' as src, count(*) as n_rows from read_parquet('s3://bronze/topics/transactions.public.ledger_entries/event_date=*/*.parquet', hive_partitioning=true, union_by_name=true) union all select 'user_accountactivity' as src, count(*) as n_rows from read_parquet('s3://bronze/topics/transactions.public.user_accountactivity/event_date=*/*.parquet', hive_partitioning=true, union_by_name=true)